class Solution:
    def findMaximumLength(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0]
        pre.extend(nums)
        dp = {}
        dp[0] = (0, 0)
        i = 0

        while i <= n:
            length, x = dp.get(i - 1, (0, 0))
            x = -x

            if x <= nums[i - 1]:
                dp[i] = max(dp.get(i, (0, 0)), (length + 1, -nums[i - 1]))
            else:
                dp[i] = max(dp.get(i, (0, 0)), (length, -(x + nums[i - 1])))

            lb_need = pre[i] - nums[i - 1] + x
            id_val = None
            for j in range(i + 1, n + 1):
                if pre[j] >= lb_need:
                    id_val = j
                    break

            if id_val is not None and id_val <= n:
                dp[id_val] = max(dp.get(id_val, (0, 0)), (length + 1, -(x + pre[id_val] - lb_need)))

            i += 1

        return dp[n][0]

