class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        ans = 0
        # Iterate over i from 0 to 2^n - 1 (bitmask representing closed branches)
        for i in range(1 << n):
            # Initialize g as a matrix with dimensions n x n, filled with infinity
            g = [[float('inf')] * n for _ in range(n)]
            # Set g[i][i] = 0 for each j in range(n)
            for j in range(n):
                g[j][j] = 0

            # Iterate through each road (x, y, w) in roads
            for road in roads:
                x, y, w = road
                # Check if both branches x and y are active in bitmask i
                if (x & i) == 0 and (y & i) == 0:
                    # Set g[x][y] and g[y][x] to the minimum of their current value and w
                    g[x][y] = min(g[x][y], w)
                    g[y][x] = min(g[y][x], w)

            # Apply Floyd-Warshall algorithm to calculate shortest paths
            for k in range(n):
                for i_idx in range(n):
                    for j_idx in range(n):
                        g[i_idx][j_idx] = min(g[i_idx][j_idx], g[i_idx][k] + g[k][j_idx])

            # Initialize ok = 1 (flag to check maxDistance constraint)
            ok = 1
            # Iterate over each pair of branches (j, k)
            for j in range(n):
                for k in range(n):
                    # Check if both branches j and k are active in bitmask i
                    if (j & i) == 0 and (k & i) == 0:
                        # Check if distance is within maxDistance
                        if g[j][k] > maxDistance:
                            ok = 0
                            break
                if not ok:
                    break

            # If all pairs satisfy the distance constraint, increment ans
            if ok:
                ans += 1

        return ans

